class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_mib = monthly_limit_mib
        self.uploads = {}  # Maps (month, name) -> size_bytes

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("File size cannot be 0")

        # Check if this file already exists for this month
        if (month, name) in self.uploads:
            return

        self.uploads[(month, name)] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Remove the file from tracking if it exists for this month
        if (month, name) in self.uploads:
            del self.uploads[(month, name)]

    def used_bytes(self, month: str) -> int:
        # Sum all bytes for files uploaded in the given month
        total = 0
        for (m, _), size in self.uploads.items():
            if m == month:
                total += size
        return total
